"""Whole-file lessons for configuration, embedded data and access policy."""
ROWS=[]


def add(path,title,intro,principle,use,sections,questions):
    ROWS.append(dict(path=path,title=title,intro=intro,principle=principle,use=use,
                     area='빌드·개발 도구·접근 정책',sections=sections,questions=questions))


add('.cocciconfig','Coccinelle 설정 전체: 검색 방식과 시간 예산',
    '커널 소스에는 실행 코드뿐 아니라 개발 도구의 기본 동작을 정하는 설정도 있습니다.',
    '[spatch] 절의 두 options 항목은 --timeout 200과 --use-gitgrep입니다. 전자는 분석 시간 제한 옵션, 후자는 git grep을 이용할 수 있다는 힌트입니다. Linux의 coccinelle.rst도 이 두 설정을 설명합니다.',
    '이 파일은 커널 부팅 때 실행하는 셸 스크립트가 아니라 spatch가 읽는 설정입니다. 적용 옵션은 spatch --print-options-only로 확인할 수 있으며 구성 우선순위와 SPFLAGS를 통한 override를 함께 확인합니다.',
    [('파일 전체','절 이름 하나와 옵션 두 줄이 전부입니다. 같은 options 이름이 반복된다고 일반 JSON의 중복 키처럼 앞 항목을 반드시 버린다고 해석하면 안 됩니다. 이 도구의 설정 파서와 문서가 옵션 해석을 결정합니다.'),
     ('원본 문서와 연결','Documentation/dev-tools/coccinelle.rst의 설정 설명은 Linux의 .cocciconfig가 git grep 사용과 200초 timeout을 제공한다고 명시합니다. 적용 옵션이 프로세스 명령줄에 그대로 나타나지 않을 수 있어 --print-options-only 확인을 안내합니다. M= 대상과 설정 읽기 우선순위도 영향을 줍니다.'),
     ('CS 연결','정적 분석의 계산 비용과 탐색 범위를 관리하는 설정입니다. timeout은 자원 예산을 제한할 뿐 제한 시간 내 모든 버그를 찾아냈다는 보장이 아닙니다. 도구 결과를 해석할 때 완료·중단·적용 설정을 함께 기록해야 재현 가능합니다.')],
    [('이 파일을 적용한 분석이 timeout으로 중단되면 버그가 없다고 결론 낼 수 있는가?', '아니다. 시간 예산으로 분석이 끝나지 않았을 수 있다', '그렇다. 200초면 모든 프로그램을 완전 분석한다', '시간 제한은 실행 자원의 상한이지 검증 완전성 보장이 아닙니다. 실패·중단 여부와 실제 분석 범위를 구분해야 합니다.'),
     ('문서가 안내하는 적용 옵션 확인 방법은?', 'spatch --print-options-only', '커널 uname 출력만 보기', '설정 파일에서 읽은 옵션은 프로세스 인자 목록에 드러나지 않을 수 있습니다. spatch 자체의 옵션 출력으로 실제 적용값을 확인합니다.')])

add('.get_maintainer.ignore','유지보수자 제외 목록 전체: 데이터 파일의 소비 경로',
    '이 파일은 이름과 이메일 형태의 5개 항목을 담습니다. 목록의 효과는 이를 읽는 스크립트의 사용 지점을 확인해야 알 수 있습니다.',
    'scripts/get_maintainer.pl은 선택한 .get_maintainer.ignore를 읽고 공백·주석을 정리한 뒤 유효한 RFC822 형식 줄을 모읍니다. ignore_email_address는 목록 항목과 전달 주소 문자열을 eq로 비교하고, Git 서명 통계로 후보를 추가하는 경로에서 이를 제외합니다.',
    '이 목록을 저장소 접근 차단이나 이메일 전송 차단 장치라고 해석하지 않습니다. MAINTAINERS의 모든 명시적 항목이 항상 이 목록 때문에 제거된다고도 일반화하지 말고 실제 적용 경로를 봅니다.',
    [('파일 전체','각 줄은 표시 이름과 꺾쇠 괄호 안 주소를 담는 공개 프로젝트 설정 데이터입니다. 5개 줄이며 같은 표시 이름의 다른 주소가 별도 항목으로 있습니다. 코드 실행문이나 와일드카드 규칙을 적는 파일이 아닙니다.'),
     ('읽기와 비교 방식','스크립트는 which_conf로 파일을 찾고 앞뒤 공백과 # 뒤 주석을 정리합니다. 빈 줄은 건너뛰고 rfc822_valid를 통과한 문자열만 저장합니다. 비교 helper는 $ignore eq $address로 문자열이 같은지 확인합니다. 따라서 파일에 있는 모든 이름을 임의의 다른 표현 주소와 자동으로 동일시한다고 추측하면 안 됩니다.'),
     ('CS 연결과 한계','설정 데이터→검증→후보 필터라는 처리 파이프라인입니다. 표시 이름과 실제 주소의 표현, 비교 정규화, 적용 단계가 정책 효과를 결정합니다. 이 목록은 프로그램의 출력 후보 선정용이며 계정 인증·인가 정책이 아닙니다.')],
    [('이 파일이 특정 사람의 Git 저장소 접근을 차단하는가?', '아니다. get_maintainer 후보 선정에 쓰이는 데이터다', '그렇다. 계정 접근 제어 목록이다', '소비 코드는 Git 서명 기반 이메일 후보를 넣기 전 제외 검사를 합니다. 인증·인가나 네트워크 차단 호출은 이 파일의 역할이 아닙니다.'),
     ('항목 비교 helper가 사용하는 직접 비교는?', 'Perl 문자열 eq 비교', '메일 서버에 질의해 같은 사람인지 확인', '원본 helper는 foreach로 목록을 돌며 $ignore eq $address를 검사합니다. 사람 신원 확인이나 SMTP 요청을 수행하지 않습니다.')])

add('.gitattributes','Git 속성 전체: 확장자에 맞는 diff 드라이버',
    '코드 리뷰에서 변경 문맥을 잘 읽도록 파일 유형별 diff 처리를 지정합니다.',
    '*.[ch]는 diff=cpp, *.dts와 *.dts[io]는 diff=dts, *.rs는 diff=rust를 지정합니다. 속성은 파일 내용을 컴파일하거나 포맷을 자동 수정하는 명령이 아닙니다.',
    '패턴에 맞는 파일의 diff 속성을 git check-attr로 확인합니다. [ch]와 [io]는 각각 한 글자 선택 집합이며 여러 글자 확장자 전체를 뜻하는 중괄호 목록과 다릅니다.',
    [('전체 줄 설명','SPDX 주석 뒤 네 규칙이 전부입니다. C 소스·헤더, device tree source와 include/overlay 확장자, Rust 소스를 각각 해당 언어 diff 드라이버에 연결합니다. 별도의 end-of-line, binary, merge 드라이버 속성은 이 파일에 없습니다.'),
     ('패턴 예시','a.c와 a.h는 *.[ch]에 맞고 a.cpp는 맞지 않습니다. board.dtsi와 board.dtso는 *.dts[io]에 맞으며 board.dts는 별도 *.dts 규칙이 담당합니다. lib.rs는 Rust 규칙을 사용합니다.'),
     ('CS와 협업','같은 바이트 차이라도 언어 구조에 맞는 문맥 표시는 리뷰와 원인 분석을 돕습니다. 속성은 표현 도구의 설정이지 변경의 기능적 정확성 증명이 아닙니다. 파일명이 패턴과 맞는지와 파일 내용이 그 언어로 유효한지는 별도 검사입니다.')],
    [('foo.cpp가 *.[ch] 규칙에 매칭되는가?', '아니다. 점 뒤 한 글자가 c 또는 h여야 한다', '그렇다. cpp가 c로 시작하므로 맞는다', '[ch]는 글자 하나를 소비합니다. .cpp의 pp까지 맞추는 패턴이 아니므로 그 규칙은 적용되지 않습니다.'),
     ('board.dtso에 지정되는 diff 값은?', 'dts', 'rust', '*.dts[io]에서 마지막 [io]가 o와 일치합니다. board.dtsi도 같은 규칙으로 dts 드라이버에 연결됩니다.')])

add('.rustfmt.toml','Rust 포맷 설정 전체: 활성 옵션과 주석의 차이',
    '설정 파일에 이름이 보인다고 해서 해당 기능이 실제로 활성화된 것은 아닙니다.',
    '활성 설정은 edition="2021"과 newline_style="Unix" 두 개입니다. 아래 다섯 옵션은 #으로 주석 처리되어 활성 옵션이 아닙니다. 주석은 향후 안정화되면 사용할 수 있는 실험적 포맷 기능을 남겨둔 이유를 설명합니다.',
    '포맷터의 입력 문법 edition과 줄바꿈을 맞추는 설정입니다. 이 파일만 수정한다고 Rust 컴파일러의 실제 빌드 edition이나 모든 코드 의미가 자동 변경되는 것은 아닙니다.',
    [('전체 파일','두 활성 대입 뒤에 unstable 옵션 설명 주석과 format_code_in_doc_comments, reorder_impl_items, comment_width, wrap_comments, normalize_comments의 주석 처리된 예시가 있습니다. 값이 쓰여 있어도 # 뒤 내용은 TOML의 활성 대입이 아닙니다.'),
     ('효과와 비효과','newline_style="Unix"는 포맷터 출력의 LF 줄바꿈을 지정합니다. edition="2021"은 rustfmt의 파싱·포맷 문맥 설정입니다. 주석 상태의 comment_width=100을 현재 강제되는 100글자 제한이라고 소개하면 틀립니다.'),
     ('CS 연결','구성의 유효 상태와 제안·기록 상태를 구별하는 연습입니다. 도구 버전, 지원 옵션, 실제 호출 인자가 최종 동작을 결정하므로 주석을 실행 설정으로 세면 재현 가능한 빌드나 포맷 검증을 해칠 수 있습니다.')],
    [('이 파일은 현재 comment_width=100을 활성화하는가?', '아니다. 해당 줄은 주석이다', '그렇다. 숫자가 파일에 있으므로 적용된다', '#comment_width = 100은 주석 처리되어 TOML 설정값으로 읽히지 않습니다. 활성화 의도와 현재 활성 상태는 다릅니다.'),
     ('활성 줄바꿈 설정은?', 'Unix 형식 LF', 'Windows 형식 CRLF', 'newline_style에 문자열 Unix가 지정되어 있습니다. 이 설정은 포맷터 출력 규칙이며 이미 존재하는 모든 파일이 읽는 즉시 수정된다는 뜻은 아닙니다.')])

add('lib/.gitignore','lib 생성물 제외 규칙 전체: 추적과 생성 의존성',
    '재생성 가능한 빌드 결과를 소스 변경 목록과 구별하는 여섯 규칙입니다.',
    '선행 /가 붙은 crc32table.h, crc64table.h, default.bconf, gen_crc32table, gen_crc64table, oid_registry_data.c를 이 .gitignore가 있는 lib 디렉터리 기준으로 제외합니다.',
    'ignore는 파일을 삭제하거나 빌드에서 사용하지 못하게 하는 기능이 아닙니다. 이미 Git이 추적하는 파일의 변경을 숨기는 규칙으로도 이해하면 안 됩니다. 생성 도구와 생성 입력은 별도로 추적해야 재현 가능합니다.',
    [('파일 전체','SPDX 주석과 여섯 경로 패턴이 전부입니다. CRC 전이 표 헤더 2개, 내장 bootconfig 데이터 1개, 표 생성 실행 파일 2개, OID 레지스트리 생성 C 파일 1개를 명시합니다. 패턴별 생성 목적이 다르므로 확장자가 같다고 같은 종류의 원본 코드로 분류하지 않습니다.'),
     ('경로 기준','/crc32table.h는 저장소 최상위 /crc32table.h가 아니라 이 규칙 파일의 위치를 기준으로 한 lib/crc32table.h에 해당합니다. lib/sub/crc32table.h 같은 하위 경로 전체를 재귀적으로 매칭하는 이름 패턴과 다릅니다.'),
     ('CS와 빌드','생성물과 생성 규칙을 구분하면 빌드 그래프를 이해할 수 있습니다. 예를 들어 default.bconf는 Git에서 제외되어도 bootconfig-data.S의 .incbin 입력으로 필요할 수 있습니다. ignore된 입력이 존재하지 않으면 빌드 실패를 일으킬 수 있으며 ignore가 이를 자동 생성하지 않습니다.')],
    [('lib/.gitignore의 /crc32table.h가 가리키는 것은?', 'lib/crc32table.h', '저장소 루트의 crc32table.h만', '선행 /는 그 .gitignore가 적용되는 디렉터리 기준 경로입니다. 규칙 파일 자체가 lib 안에 있습니다.'),
     ('default.bconf가 ignore되어 있으므로 .incbin에서 없어도 되는가?', '아니다. Git 제외와 빌드 입력 필요 여부는 다르다', '그렇다. assembler가 ignore 목록을 보고 생략한다', 'assembler는 .incbin이 지정한 실제 파일을 읽습니다. .gitignore는 버전 관리의 추적 대상 선정 규칙이지 assembler 실행 규칙이 아닙니다.')])

add('lib/bootconfig-data.S','Bootconfig 임베딩 전체: 기계어 없이 바이트를 포함하는 어셈블리',
    '어셈블리 파일이 모두 CPU 실행 명령을 담는 것은 아닙니다. 이 파일은 빌드 결과에 데이터 바이트를 넣습니다.',
    '.section .init.rodata,"aw"로 섹션을 선택하고 시작·끝 글로벌 심볼 사이에 .incbin "lib/default.bconf"를 배치합니다. 두 라벨의 차이는 포함된 파일의 바이트 길이입니다.',
    '생성된 default.bconf가 빌드 입력으로 준비되어야 합니다. C 쪽 lib/bootconfig.c는 두 심볼 차이로 크기를 계산하고 크기가 0이면 NULL을 반환합니다. 시작 라벨이 C 문자열의 NUL 종료까지 보장한다고 추측하면 안 됩니다.',
    [('전체 지시문','SPDX·목적 주석, .section, 시작 .global 및 라벨, .incbin, 끝 .global 및 라벨이 전체입니다. CPU branch/load/store 명령은 없습니다. .global은 링커가 다른 번역 단위의 심볼 참조를 해결할 수 있게 합니다.'),
     ('섹션 이름과 속성','이 원문은 이름이 .init.rodata이지만 명시 플래그 문자열은 aw입니다. a는 allocatable, w는 writable 속성을 뜻합니다. 섹션 이름에 rodata가 있다고 소스의 w 플래그를 없던 것으로 읽으면 안 됩니다. 최종 배치·페이지 권한은 링커 스크립트와 부팅 처리도 함께 결정합니다.'),
     ('크기와 경계','입력 파일이 N바이트면 두 라벨 사이가 N바이트입니다. end는 마지막 바이트 자체가 아니라 끝 다음 위치입니다. .incbin은 입력에 없는 NUL 바이트를 자동 덧붙이지 않습니다. 빈 파일이면 두 라벨 주소가 같아 크기가 0입니다.'),
     ('CS 연결','링크 시점 데이터 임베딩, 심볼 주소 차이, 반열린 구간 [start,end), 데이터와 실행 코드의 구별을 배웁니다. init용 데이터의 장기 수명을 당연하게 가정하지 말고 소비 경로와 초기화 메모리 해제 규칙을 확인합니다.')],
    [('입력 default.bconf가 17바이트면 end-start는?', '17', 'NUL을 자동 추가하므로 18', '.incbin은 입력 바이트를 그대로 넣습니다. 별도의 .byte 0 지시문이 없으므로 자동 NUL 추가를 가정할 수 없습니다.'),
     ('이 파일에 CPU가 실행할 명령이 반드시 있는가?', '아니다. 섹션·심볼·데이터 포함 지시문으로 구성된다', '그렇다. .S 확장자는 항상 실행 루프를 뜻한다', '확장자는 assembler 입력 형식을 나타냅니다. 내용은 데이터 배치를 위한 지시문뿐일 수 있습니다.'),
     ('원문의 섹션 플래그는 이름 rodata와 별개로 무엇인가?', '명시적으로 aw다', '항상 a만 있고 w는 없다', '원본 .section .init.rodata, "aw"를 그대로 읽어야 합니다. 이름의 관례와 실제 플래그, 최종 메모리 권한은 서로 다른 확인 대상입니다.')])

add('lib/devmem_is_allowed.c','/dev/mem 정책 전체: 물리 페이지 번호와 거절 우선순위',
    '장치 메모리와 시스템 RAM에 대한 접근 허용 결정을 작은 조건문으로 추적합니다.',
    '인자는 물리 페이지 번호 pfn입니다. PFN_PHYS(pfn) 주소가 exclusive iomem이면 먼저 0입니다. 그 검사를 통과하고 page_is_ram(pfn)이 거짓이면 1, RAM이면 0입니다.',
    '이 generic helper의 1은 해당 정책 검사를 통과했다는 뜻이지 모든 사용자에게 /dev/mem 접근 권한이 생겼다는 뜻은 아닙니다. 장치 열기 권한과 다른 정책·설정은 별도입니다.',
    [('전체 파일','SPDX·generic 구현 설명·출처·저작권, mm/ioport/io 헤더, 정책 주석, 함수 하나가 전부입니다. 함수는 주소를 읽거나 쓰지 않고 허용 여부 int를 반환합니다. pfn을 바이트 주소로 변환하는 곳과 pfn 그대로 분류하는 곳이 나뉩니다.'),
     ('조건표','exclusive=true이면 RAM 여부와 관계없이 0입니다. exclusive=false이고 RAM=true이면 0입니다. exclusive=false이고 RAM=false인 조합만 1입니다. 첫 조건이 거절 우선순위를 가지므로 비-RAM이라는 사실만으로 exclusive MMIO를 통과할 수 없습니다.'),
     ('단위와 CS','페이지 번호와 바이트 주소를 섞으면 잘못된 물리 구간을 검사하게 됩니다. PFN_PHYS가 필요한 이유입니다. 이 함수는 접근 제어 파이프라인의 한 단계이며 결과를 인증·인가 전체의 결론으로 확대하지 않습니다. 코드 자체의 분기는 고정 횟수지만 helper 내부 자료 검색 비용까지 단정하지 않습니다.')],
    [('비-RAM이지만 exclusive iomem이면 결과는?', '0: 먼저 exclusive 조건에서 거절', '1: RAM이 아니므로 항상 허용', 'exclusive 검사가 첫 번째 조기 반환입니다. page_is_ram까지 도달하지 않아 비-RAM 여부가 이 거절을 뒤집지 못합니다.'),
     ('함수 인자 pfn은 무엇인가?', '물리 페이지 번호', '이미 바이트 단위인 가상 주소', '원문 주석과 PFN_PHYS(pfn) 변환이 물리 페이지 번호 계약을 보여줍니다. iomem 주소 검사에는 변환된 물리 바이트 주소를 사용합니다.'),
     ('반환 1이면 어떤 사용자의 /dev/mem 읽기도 무조건 성공하는가?', '아니다. 이 helper 이외의 접근 조건이 남을 수 있다', '그렇다. 파일 접근 권한도 자동 변경한다', '본문은 파일 권한을 바꾸거나 사용자 신원을 승인하지 않습니다. 해당 물리 구간의 generic 정책 분기 결과만 돌려줍니다.')])
